namespace Drover.Presentation.Tests.Diagnostics;

/// <summary>
/// The diagnostic log keeps only what is known to be safe. Each case hands the real logging pipeline a secret in a
/// different place, generated by the test, and checks the saved file never holds it while the useful parts remain.
/// </summary>
public sealed class DiagnosticRedactionTests : IDisposable
{
    #region Private Fields

    private static readonly AppDescription app = new("9.8.7-test", "Test platform");

    private readonly MemoryDiagnosticStore store = new();

    private readonly FakeTimeProvider time = new(new DateTimeOffset(2026, 11, 19, 9, 30, 0, TimeSpan.Zero));

    private readonly DiagnosticLog log;

    private readonly ILoggerFactory factory;

    private readonly string token = $"Bearer drover-test-{Guid.NewGuid():N}";

    private readonly string cookie = $".AspNetCore.Cookies={Guid.NewGuid():N}";

    private readonly Guid sessionId = Guid.NewGuid();

    private readonly string password = $"pw-{Guid.NewGuid():N}";

    private readonly string server = $"https://host-{Guid.NewGuid():N}.example.test";

    private readonly string messageText = $"Please book the dentist for {Guid.NewGuid():N}";

    #endregion

    #region Constructors

    public DiagnosticRedactionTests()
    {
        log = new(store, time);
        factory = LoggerFactory.Create(logging => logging.AddProvider(new DiagnosticLogProvider(log, time)));
    }

    #endregion

    #region Public Methods

    public void Dispose() => factory.Dispose();

    [Fact]
    public void Text_values_are_left_out_and_the_template_is_kept()
    {
        var logger = factory.CreateLogger<DiagnosticRedactionTests>();

        logger.LogWarning(
            "Signing in to {Server} with {Authorization} and {Cookie} for session {SessionId} said {Text}",
            server, token, cookie, sessionId, messageText);

        var saved = log.Compose(app);
        saved.Should().Contain(
            "Signing in to {Server} with {Authorization} and {Cookie} for session {SessionId} said {Text}");
        ShouldHoldNoSecret(saved);
    }

    [Fact]
    public void Tool_arguments_given_as_an_object_are_left_out()
    {
        var logger = factory.CreateLogger<DiagnosticRedactionTests>();
        var arguments = new Dictionary<string, object?> { ["password"] = password, ["to"] = server };

        logger.LogError("A tool call failed with {Arguments}", arguments);
        logger.LogError("A tool call failed with {Arguments}", new { Password = password, Body = messageText });

        var saved = log.Compose(app);
        saved.Should().Contain("A tool call failed with {Arguments}");
        ShouldHoldNoSecret(saved);
    }

    [Fact]
    public void Plain_values_that_cannot_hold_text_are_kept()
    {
        var logger = factory.CreateLogger<DiagnosticRedactionTests>();

        logger.LogWarning(
            "The server answered {Status} after {Attempts} tries in {Elapsed}",
            HttpStatusCode.Unauthorized, 3, TimeSpan.FromSeconds(2));

        log.Compose(app).Should().Contain("Status=Unauthorized Attempts=3 Elapsed=00:00:02");
    }

    [Fact]
    public void A_library_message_built_from_values_is_left_out_whole()
    {
        var logger = factory.CreateLogger("Uno.UI.Sample.Library");

#pragma warning disable CA2254 // The case under test: a library that builds its message from values.
        logger.LogWarning($"Request to {server} with {token} failed");
#pragma warning restore CA2254

        var saved = log.Compose(app);
        saved.Should().Contain("warning Uno.UI.Sample.Library: (message not kept)");
        ShouldHoldNoSecret(saved);
    }

    [Fact]
    public void An_exception_keeps_its_type_and_places_but_not_its_message()
    {
        var logger = factory.CreateLogger<DiagnosticRedactionTests>();

        logger.LogError(Thrown(), "A request to the server failed on the {Screen} screen", "Sample");

        var saved = log.Compose(app);
        saved.Should().Contain(typeof(HttpRequestException).FullName)
            .And.Contain("caused by")
            .And.Contain(typeof(InvalidOperationException).FullName)
            .And.Contain($"{nameof(DiagnosticRedactionTests)}.{nameof(Thrown)}")
            .And.Contain($"in {nameof(DiagnosticRedactionTests)}.cs:line ")
            .And.NotContain(Path.GetDirectoryName(ThisFile())!);
        ShouldHoldNoSecret(saved);
    }

    [Fact]
    public void An_unhandled_failure_is_saved_with_the_app_version_and_no_secret()
    {
        log.RecordFailure(Thrown());

        var saved = log.Compose(app);
        saved.Should().Contain("App version: 9.8.7-test")
            .And.Contain("Platform: Test platform")
            .And.Contain("2026-11-19T09:30:00.000Z unhandled failure")
            .And.Contain(typeof(HttpRequestException).FullName);
        ShouldHoldNoSecret(saved);
        ShouldHoldNoSecret(store.All);
    }

    [Fact]
    public void Information_and_below_is_not_kept()
    {
        var logger = factory.CreateLogger<DiagnosticRedactionTests>();

        logger.LogInformation("Opened the {Screen} screen", "Sample");

        log.Compose(app).Should().Contain("Nothing logged.");
    }

    #endregion

    #region Private Methods

    private void ShouldHoldNoSecret(string saved)
    {
        string[] secrets =
        [
            token, token["Bearer ".Length..], cookie, sessionId.ToString(), sessionId.ToString("N"), password, server,
            messageText,
        ];
        foreach (var secret in secrets)
        {
            saved.Should().NotContain(secret);
        }
    }

    private HttpRequestException Thrown()
    {
        try
        {
            try
            {
                throw new InvalidOperationException($"{password} was refused by {server}");
            }
            catch (InvalidOperationException inner)
            {
                throw new HttpRequestException(
                    $"POST {server}/api/messages with {token} and {cookie}: {messageText}", inner);
            }
        }
        catch (HttpRequestException exception)
        {
            return exception;
        }
    }

    private static string ThisFile([System.Runtime.CompilerServices.CallerFilePath] string path = "") => path;

    #endregion
}
